using System.IO.Compression;
using System.Runtime.InteropServices;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using Starlings.Acquisition;
using Starlings.Models.EmbeddingGemma2;
using Starlings.Models.EmbeddingGemma2.Imaging.SkiaSharp;

namespace Starlings.TestSupport;

/// <summary>
/// The accepted EmbeddingGemma 2 image fixtures (read only, in Git), the image set (not in Git: regenerated byte for byte
/// by <c>model-pipeline/reference/embeddinggemma2/make_eg2_images.py</c>), the reference tensors (not in Git: the
/// <c>.npz</c> files of <c>run_embeddinggemma2_image.py --tensors</c>, pinned by <c>tensors.json</c>) and the image graphs
/// (not in Git). Tests that need an absent asset skip with the reason.
/// </summary>
internal static class EmbeddingGemma2ImageTestAssets
{
    /// <summary>Directory holding the 29 images and <c>images.json</c> from <c>make_eg2_images.py</c>.</summary>
    public const string ImagesEnvironmentVariable = "STARLING_EMBEDDINGGEMMA2_IMAGES";

    /// <summary>Directory holding the reference <c>&lt;row id&gt;.npz</c> tensors (optional; soft-token and token-embedding checks).</summary>
    public const string TensorsEnvironmentVariable = "STARLING_EMBEDDINGGEMMA2_IMAGE_TENSORS";

    /// <summary>The 16-bit PNG: upstream renders it white; the decoder rejects it, so no C# path reproduces its row.</summary>
    public const string SixteenBitImageId = "mode-gray16";

    /// <summary>Accepted image fixtures (PR #42).</summary>
    public static string FixtureDirectory => Path.Combine(EmbeddingGemma2TestAssets.ProtectedRoot, "image-fp32-cpu");

    /// <summary>The image set: <c>$STARLING_EMBEDDINGGEMMA2_IMAGES</c>, else <c>&lt;models&gt;/embeddinggemma-2-images</c>.</summary>
    public static string ImagesDirectory =>
        Environment.GetEnvironmentVariable(ImagesEnvironmentVariable) is { Length: > 0 } env
            ? env
            : Path.Combine(EmbeddingGemma2TestAssets.ModelsRoot, "embeddinggemma-2-images");

    public static IReadOnlyList<ImageManifestEntry> Manifest { get; } = LoadManifest();

    public static IReadOnlyList<ImageRow> Rows { get; } = LoadRows();

    /// <summary>Null when every image file is present with its pinned SHA-256; otherwise the skip reason.</summary>
    public static string? ImagesSkipReason { get; } = CheckImages();

    /// <summary>The image files' bytes by id; skips the calling test when the image set is absent.</summary>
    public static byte[] ReadImageFile(string id)
    {
        Assert.SkipWhen(ImagesSkipReason is not null, ImagesSkipReason ?? string.Empty);
        var entry = Manifest.Single(m => m.Id == id);
        return File.ReadAllBytes(Path.Combine(ImagesDirectory, entry.File));
    }

    private static readonly Dictionary<string, EmbeddingGemma2Image> DecodedCache = new(StringComparer.Ordinal);

    /// <summary>The image decoded by the SkiaSharp adapter (checked equal to PIL's RGB by the adapter tests).</summary>
    public static EmbeddingGemma2Image Decode(string id)
    {
        lock (DecodedCache)
        {
            if (!DecodedCache.TryGetValue(id, out var image))
            {
                image = EmbeddingGemma2ImageDecoder.Decode(ReadImageFile(id));
                DecodedCache[id] = image;
            }

            return image;
        }
    }

    /// <summary>The input of a fixture row built from decoded images (or from images of the right size when <paramref name="imageFor"/> returns placeholders).</summary>
    public static EmbeddingGemma2MultimodalInput BuildInput(ImageRow row, Func<string, EmbeddingGemma2Image> imageFor)
    {
        var images = row.Images.Select(i => imageFor(i.Image)).ToList();
        if (row.Text is null)
        {
            return images.Count == 0 ? EmbeddingGemma2MultimodalInput.FromText(string.Empty) : EmbeddingGemma2MultimodalInput.Create(images.Cast<object>());
        }

        if (images.Count == 0)
        {
            return EmbeddingGemma2MultimodalInput.FromText(row.Text);
        }

        // Upstream: <|image|> in the text marks the image positions; without one, images follow the text.
        var pieces = row.Text.Split("<|image|>");
        var parts = new List<object>();
        if (pieces.Length == 1)
        {
            parts.Add(row.Text);
            parts.AddRange(images);
        }
        else
        {
            Assert.Equal(images.Count, pieces.Length - 1);
            for (int i = 0; i < pieces.Length; i++)
            {
                parts.Add(pieces[i]);
                if (i < images.Count)
                {
                    parts.Add(images[i]);
                }
            }
        }

        return EmbeddingGemma2MultimodalInput.Create(parts);
    }

    /// <summary>A zero image of an image's decoded size (rendering and tokenization depend only on the size).</summary>
    public static EmbeddingGemma2Image SizedPlaceholder(string id)
    {
        var m = Manifest.Single(x => x.Id == id);
        return EmbeddingGemma2Image.FromRgb24(m.Width, m.Height, new byte[(long)m.Width * m.Height * 3]);
    }

    /// <summary>The image model files (offline), or null with the reason.</summary>
    public static (EmbeddingGemma2ImageModelFiles? Files, string Reason) FindImageModel()
    {
        string? snapshot = Environment.GetEnvironmentVariable(EmbeddingGemma2TestAssets.SnapshotEnvironmentVariable);
        try
        {
            var files = string.IsNullOrEmpty(snapshot)
                ? EmbeddingGemma2ModelAssets.OpenLocalImageAssets(new ModelAcquisitionOptions { CacheDirectory = EmbeddingGemma2TestAssets.ModelsRoot, Verification = CacheVerification.Size })
                : EmbeddingGemma2ModelAssets.OpenImageDirectory(snapshot, CacheVerification.Size);
            return (files, string.Empty);
        }
        catch (ModelAssetMissingException ex)
        {
            return (null, ex.Message + $" Alternatively set {EmbeddingGemma2TestAssets.SnapshotEnvironmentVariable} to a directory with tokenizer.json, config_sentence_transformers.json, " +
                          $"{EmbeddingGemma2ModelAssets.ModelFile}, {EmbeddingGemma2ModelAssets.VisionModelFile} and {EmbeddingGemma2ModelAssets.MultimodalModelFile} " +
                          "(model-pipeline/reference/embeddinggemma2/release_embeddinggemma2_vision_onnx.py).");
        }
    }

    /// <summary>The tensors directory, or null with the reason.</summary>
    public static (string? Directory, string Reason) FindTensors()
    {
        string? dir = Environment.GetEnvironmentVariable(TensorsEnvironmentVariable);
        if (string.IsNullOrEmpty(dir) || !Directory.Exists(dir))
        {
            return (null, $"set {TensorsEnvironmentVariable} to the directory of run_embeddinggemma2_image.py --tensors output (<row id>.npz) for the soft-token and token-embedding checks.");
        }

        return (dir, string.Empty);
    }

    private static readonly JsonElement TensorDigests = JsonDocument.Parse(File.ReadAllText(Path.Combine(FixtureDirectory, "tensors.json"))).RootElement;

    /// <summary>A float32 array of a row's <c>.npz</c>, checked against the SHA-256 in <c>tensors.json</c>.</summary>
    public static float[] ReadReferenceTensor(string directory, string rowId, string name)
    {
        using var zip = ZipFile.OpenRead(Path.Combine(directory, rowId + ".npz"));
        var entry = zip.GetEntry(name + ".npy") ?? throw new InvalidDataException($"{rowId}.npz has no {name}.");
        using var stream = entry.Open();
        using var buffer = new MemoryStream();
        stream.CopyTo(buffer);
        var bytes = buffer.ToArray();
        if (bytes.Length < 10 || bytes[0] != 0x93 || Encoding.ASCII.GetString(bytes, 1, 5) != "NUMPY")
        {
            throw new InvalidDataException($"{rowId}/{name}: not an .npy file");
        }

        int headerLength = bytes[6] == 1 ? BitConverter.ToUInt16(bytes, 8) : BitConverter.ToInt32(bytes, 8);
        int offset = (bytes[6] == 1 ? 10 : 12) + headerLength;
        string header = Encoding.ASCII.GetString(bytes, bytes[6] == 1 ? 10 : 12, headerLength);
        if (!header.Contains("'descr': '<f4'", StringComparison.Ordinal) || header.Contains("'fortran_order': True", StringComparison.Ordinal))
        {
            throw new InvalidDataException($"{rowId}/{name}: expected C-ordered little-endian float32, header {header}");
        }

        var data = bytes.AsSpan(offset);
        string expected = TensorDigests.GetProperty(rowId).GetProperty(name).GetProperty("sha256").GetString()!;
        string actual = Convert.ToHexStringLower(SHA256.HashData(data));
        if (actual != expected)
        {
            throw new InvalidDataException($"{rowId}/{name}: SHA-256 {actual} differs from tensors.json {expected}; not the reference tensors.");
        }

        return MemoryMarshal.Cast<byte, float>(data).ToArray();
    }

    /// <summary>SHA-256 of raw values, as the reference's <c>sha(np.ascontiguousarray(a).tobytes())</c>.</summary>
    public static string Sha<T>(ReadOnlySpan<T> values)
        where T : unmanaged => Convert.ToHexStringLower(SHA256.HashData(MemoryMarshal.AsBytes(values)));

    private static List<ImageManifestEntry> LoadManifest()
    {
        using var doc = JsonDocument.Parse(File.ReadAllText(Path.Combine(FixtureDirectory, "images.json")));
        return doc.RootElement.GetProperty("images").EnumerateArray().Select(i => new ImageManifestEntry(
            i.GetProperty("id").GetString()!,
            i.GetProperty("file").GetString()!,
            i.GetProperty("format").GetString()!,
            i.GetProperty("mode").GetString()!,
            i.GetProperty("width").GetInt32(),
            i.GetProperty("height").GetInt32(),
            i.GetProperty("sha256").GetString()!,
            i.TryGetProperty("exif_orientation", out var o) && o.ValueKind == JsonValueKind.Number ? o.GetInt32() : null)).ToList();
    }

    private static List<ImageRow> LoadRows() =>
        EmbeddingGemma2TestAssets.ReadJsonLines(Path.Combine(FixtureDirectory, "image-embeddings.jsonl"))
            .Select(r => new ImageRow(
                r.GetProperty("id").GetString()!,
                r.GetProperty("kind").GetString()!,
                r.GetProperty("prompt").GetString()!,
                r.GetProperty("text").ValueKind == JsonValueKind.Null ? null : r.GetProperty("text").GetString(),
                r.GetProperty("images").EnumerateArray().Select(i => new ImageRowImage(
                    i.GetProperty("image").GetString()!,
                    i.GetProperty("rgb_sha256").GetString()!,
                    i.GetProperty("resized").GetProperty("width").GetInt32(),
                    i.GetProperty("resized").GetProperty("height").GetInt32(),
                    i.GetProperty("soft_tokens").GetInt32(),
                    i.GetProperty("digests").GetProperty("resized_uint8").GetString()!,
                    i.GetProperty("digests").GetProperty("pixel_values").GetString()!,
                    i.GetProperty("digests").GetProperty("positions").GetString()!)).ToList(),
                r.GetProperty("input_ids").EnumerateArray().Select(e => e.GetInt64()).ToArray(),
                r.GetProperty("embedding").EnumerateArray().Select(e => e.GetSingle()).ToArray()))
            .ToList();

    private static string? CheckImages()
    {
        string dir = ImagesDirectory;
        foreach (var m in Manifest)
        {
            string path = Path.Combine(dir, m.File);
            if (!File.Exists(path))
            {
                return $"image set not found ({path}); regenerate it with model-pipeline/reference/embeddinggemma2/make_eg2_images.py --out <dir> and set {ImagesEnvironmentVariable}.";
            }

            string sha = Convert.ToHexStringLower(SHA256.HashData(File.ReadAllBytes(path)));
            if (sha != m.Sha256)
            {
                throw new InvalidDataException($"{path}: SHA-256 {sha} differs from images.json {m.Sha256}; not the fixture image set.");
            }
        }

        return null;
    }
}

/// <summary>One image of <c>images.json</c>.</summary>
internal sealed record ImageManifestEntry(string Id, string File, string Format, string Mode, int Width, int Height, string Sha256, int? ExifOrientation);

/// <summary>One image of a fixture row, with the reference digests of its preprocessing.</summary>
internal sealed record ImageRowImage(string Image, string RgbSha256, int ResizedWidth, int ResizedHeight, int SoftTokens, string ResizedSha256, string PixelValuesSha256, string PositionsSha256);

/// <summary>One row of <c>image-embeddings.jsonl</c>.</summary>
internal sealed record ImageRow(string Id, string Kind, string Prompt, string? Text, IReadOnlyList<ImageRowImage> Images, long[] InputIds, float[] Embedding)
{
    public EmbeddingGemma2Prompt PackagePrompt => EmbeddingGemma2Prompt.FromName(Prompt);

    /// <summary>True when the row reaches the C# contract (the 16-bit PNG is rejected by contract).</summary>
    public bool InContract => Images.All(i => i.Image != EmbeddingGemma2ImageTestAssets.SixteenBitImageId);
}
